package com.elitedarkkaiser.nubialy;
import org.junit.Test;import static org.junit.Assert.*;
public class PaletteTest {
 @Test public void batteryTextMigratesAndIsIndependent(){var old=SurfaceStyle.Palette.decode("0:0:-65281:0:0:0:0:0");assertNotNull(old);assertEquals(0,old.batteryText());var p=old.with(8,0xffffffff);assertEquals(0xffff00ff,p.battery());assertEquals(p,SurfaceStyle.Palette.decode(p.encode()));assertEquals(p,SurfaceStyle.decode(SurfaceStyle.STOCK.withPalette(p).encode()).palette());assertTrue(p.statusAny());assertFalse(p.with(8,0x88112233).valid());assertEquals(p,SurfaceStyle.Palette.merge(old,p,"status_bar","colors"));assertEquals(old,SurfaceStyle.Palette.merge(old,p,"quick_settings","brightness"));}
 @Test public void paletteRoundTripsAndSurvivesOtherSurfaceCopies(){var p=SurfaceStyle.Palette.STOCK.with(0,0xff123456).with(4,0xff334455).with(7,1);var s=SurfaceStyle.STOCK.withPalette(p);assertTrue(s.valid());assertEquals(s,SurfaceStyle.decode(s.encode()));assertEquals(p,s.withBatteryStyle(2).withBatteryControls(1,1).withQsTheme(SurfaceStyle.QsTheme.STOCK.with(9,1)).palette());assertEquals(SurfaceStyle.Palette.STOCK,SurfaceStyle.decode(SurfaceStyle.STOCK.encode()).palette());assertFalse(p.with(0,0x44112233).valid());assertFalse(p.with(7,2).valid());assertNull(SurfaceStyle.Palette.decode(p.encode()+":9:9"));}
 @Test public void applyingOrRestoringOneColorAreaLeavesTheOtherAreaAlone(){var palette=SurfaceStyle.Palette.STOCK.with(0,0xff123456).with(2,0xffabcdef).with(4,0xff334455).with(7,1);var active=AppearanceScope.Snapshot.STOCK;var draft=new AppearanceScope.Snapshot(StatusBarStyle.STOCK.withSurfaces(SurfaceStyle.STOCK.withPalette(palette)),active.color(),active.date(),active.clock());var status=AppearanceScope.merge("status_bar","tab_colors",active,draft);assertEquals(palette.wifi(),status.bar().surfaces().palette().wifi());assertFalse(status.bar().surfaces().palette().brightnessAny());var both=AppearanceScope.merge("quick_settings","tab_brightness",status,draft);assertEquals(palette,both.bar().surfaces().palette());var restored=AppearanceScope.merge("status_bar","tab_colors",both,active);assertFalse(restored.bar().surfaces().palette().statusAny());assertTrue(restored.bar().surfaces().palette().brightnessAny());assertEquals(both,AppearanceScope.merge("status_bar","tab_clock",both,draft));}
}
